# Read the locales module - look for month-related strings
with open('arrow/locales.py') as f:
    content = f.read()

# Find EnglishLocale class and month-related methods
lines = content.split('\n')
in_english = False
for i, line in enumerate(lines):
    if 'class EnglishLocale' in line:
        in_english = True
    if in_english and (line.startswith('class ') and 'EnglishLocale' not in line):
        break
    if in_english and ('month' in line.lower()):
        print(f"{i+1}: {line}")
